// Verifies the HMAC signature Convex puts on every loan event, then checks for duplicates.
// Secret: LENDLOOP_TO_N8N_SECRET in the n8n environment (not stored in this workflow).
const crypto = require('crypto');
const TOLERANCE_SECONDS = 300;

const secret = $env.LENDLOOP_TO_N8N_SECRET;
if (!secret) throw new Error('LENDLOOP_TO_N8N_SECRET is not set in the n8n environment');

const item = $input.first();
const headers = item.json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '').toLowerCase();

// Verify against the exact bytes Convex sent (raw body), not a re-serialised copy.
let raw;
if (item.binary && item.binary.data) {
  raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
} else {
  raw = JSON.stringify(item.json.body);
}

const reject = (reason) => [{ json: { valid: false, reason } }];
const ts = Number(timestamp);
if (!/^[0-9a-f]{64}$/.test(signature) || !Number.isInteger(ts)) return reject('missing or malformed signature');
if (Math.abs(Date.now() / 1000 - ts) > TOLERANCE_SECONDS) return reject('stale timestamp');

const expected = crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(signature, 'hex'))) return reject('bad signature');

const event = JSON.parse(raw);

// Convex retries when it doesn't get a 2xx (e.g. a timeout after we already notified).
// eventIds we've already handled are kept in workflow static data, so a retry isn't sent twice.
const seen = $getWorkflowStaticData('global').seenEventIds || [];
return [{ json: { valid: true, duplicate: seen.includes(event.eventId), event } }];

// Mock notification channel: the message is written to the n8n log (`docker compose logs n8n`).
// To go live, replace this node with Email / Slack / Discord. It only receives what it needs:
// recipient name + email, tool name, dates, and the other person's first name.
const { event } = $input.first().json;
const { recipient, loan, counterpartyName: who } = event;
if (!recipient.email) throw new Error(`No email address for recipient of ${event.eventId}`);

const dates = `${loan.startDate} to ${loan.endDate}`;
const messages = {
  'loan.created': `${who} would like to borrow your ${loan.toolName} (${dates}). Approve or decline it in LendLoop.`,
  'loan.cancelled': `${who} withdrew their request for your ${loan.toolName}.`,
  'loan.approved': `${who} approved your request for the ${loan.toolName} (${dates}).`,
  'loan.declined': `Your request for the ${loan.toolName} (${dates}) was declined.`,
  'loan.returned': `${who} marked the ${loan.toolName} as returned. Thanks for borrowing responsibly!`,
  'loan.listing_removed': `The ${loan.toolName} listing was removed, so your request (${dates}) was cancelled.`,
};
const text = `Hi ${recipient.name}, ${messages[event.type] || `there's an update on ${loan.toolName}.`}`;
console.log(`[LendLoop notification] to=${recipient.email} type=${event.type} id=${event.eventId} :: ${text}`);

// Remember this eventId only after the send succeeded, so a failed send can still be retried.
const data = $getWorkflowStaticData('global');
data.seenEventIds = [...(data.seenEventIds || []), event.eventId].slice(-1000);

return [{ json: { ok: true, eventId: event.eventId, channel: 'log' } }];
